-- Pirate Panic subarea (bonus 1, bonus 2, warp): level table built from the data
-- generated by tools/replay-compare/export_subareas.py (same ship-deck map as the main
-- area, DATA_B5BE25 area bounds). original_semantics keeps the original player rules.
-- APPROXIMATIONS: legacy follow camera clamped to the room; no BG3 rigging layer.
local render_info = require("data.original.pirate.render_info")

local function decode_rle(s, n)
  local out, idx, i = {}, 1, 1
  while idx <= n and i <= #s do
    local colon = s:find(":", i, true)
    if not colon then break end
    local comma = s:find(",", colon + 1, true)
    local v = tonumber(s:sub(i, colon - 1)) or 0
    local cnt = tonumber(s:sub(colon + 1, (comma and comma - 1) or #s)) or 0
    for _ = 1, cnt do out[idx] = v; idx = idx + 1 end
    i = comma and comma + 1 or #s + 1
  end
  while idx <= n do out[idx] = -1; idx = idx + 1 end
  return out
end

local TILE, SPAWN_H = 16, 24

return function(data)
  local cols, rows = math.floor(data.width_px / TILE), math.floor(data.height_px / TILE)
  local tiles = {}
  for r = 1, rows do
    local row = {}
    for c = 1, cols do row[c] = 0 end
    tiles[r] = row
  end
  local spawn = data.spawns[1]
  return {
    id = "1-1-" .. data.name,
    name = "Pirate Panic " .. data.name,
    subarea = data.name,
    original_semantics = true,
    prototype = false,
    width = cols,
    height = rows,
    tile_size = TILE,
    player_render_info = render_info.player,
    flat_surfaces = {
      cols = data.surface_cols, rows = data.surface_rows,
      heights = decode_rle(data.surface_rle, data.surface_cols * data.surface_rows),
    },
    player_spawn = { x = spawn.x, y = spawn.feet_y - SPAWN_H },
    spawns = data.spawns,
    goal = { x = 0, y = 0 },
    camera = { bound_x = data.width_px, bound_y = data.height_px },
    parallax = { bg = 0.25, far = 0.5, mid = 0.75 },
    chunks = data.chunks,
    tiles = tiles,
    objects = {},                      -- no legacy placeholder objects
    original_objects = data.objects,   -- consumed by the original_* modules
  }
end
